package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	_ "github.com/shopspring/decimal"
)

// FD PART-FILE record
type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                           // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20)         // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                               // PIC 99 len=2 = 0
var WsTotalA int64 = 0                               // PIC 999 len=3 = 0
var WsCount int64 = 0                                // PIC 999 len=3 = 0

// current record buffer and file image
var curRec PartRec
var inputLines []string
var inputIdx int

func truncToWidth(val int64, width int) int64 {
	if width <= 0 {
		return 0
	}
	pow := int64(1)
	for i := 0; i < width; i++ {
		pow *= 10
	}
	if val >= 0 {
		return val % pow
	}
	return -((-val) % pow)
}

func formatPic9(val int64, width int) string {
	v := truncToWidth(val, width)
	if v < 0 {
		v = -v
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func delimitedBySpace(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == ' ' {
			return s[:i]
		}
	}
	return s
}

func openPartFile() error {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
			inputIdx = 0
			return nil
		}
		return err
	}
	if len(data) == 0 {
		inputLines = []string{}
		inputIdx = 0
		return nil
	}
	s := string(data)
	parts := strings.Split(s, "\n")
	if strings.HasSuffix(s, "\n") {
		if len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
	}
	for i, p := range parts {
		if strings.HasSuffix(p, "\r") {
			parts[i] = strings.TrimSuffix(p, "\r")
		}
	}
	inputLines = parts
	inputIdx = 0
	return nil
}

func closePartFile() {
	// nothing to do for LINE SEQUENTIAL input
}

// READ-PARA
func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	raw := inputLines[inputIdx]
	inputIdx++
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	curRec.LbPart = raw[0:8]
	curRec.LbRegion = raw[8:11]
	numStr := raw[11:15]
	trimmed := strings.TrimSpace(numStr)
	if trimmed == "" {
		curRec.LbSerial = 0
	} else {
		v, err := strconv.ParseInt(trimmed, 10, 64)
		if err != nil {
			// fallback: keep only digits
			digits := ""
			for _, ch := range trimmed {
				if ch >= '0' && ch <= '9' {
					digits += string(ch)
				} else if ch == '-' {
					digits += string(ch)
				}
			}
			if digits == "" {
				v = 0
			} else {
				v, _ = strconv.ParseInt(digits, 10, 64)
			}
		}
		curRec.LbSerial = truncToWidth(v, 4)
	}
}

// PROCESS-PARA
func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := strings.Count(curRec.LbPart, "A")
	WsACount = truncToWidth(WsACount+int64(cnt), 2)

	// STRING LB-REGION DELIMITED BY SPACE "-" DELIMITED BY SIZE
	//        LB-PART DELIMITED BY SPACE "-" DELIMITED BY SIZE
	//        LB-SERIAL DELIMITED BY SIZE INTO WS-LABEL
	regionPart := delimitedBySpace(curRec.LbRegion)
	partPart := delimitedBySpace(curRec.LbPart)
	serialStr := formatPic9(curRec.LbSerial, 4)
	raw := regionPart + "-" + partPart + "-" + serialStr
	if len(raw) > 20 {
		WsLabel = raw[:20]
	} else {
		WsLabel = raw + strings.Repeat(" ", 20-len(raw))
	}
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = truncToWidth(WsTotalA+WsACount, 3)
	// ADD 1 TO WS-COUNT
	WsCount = truncToWidth(WsCount+1, 3)

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	line := WsLabel + " A=" + formatPic9(WsACount, 2)
	fmt.Fprintln(os.Stdout, line)

	// PERFORM READ-PARA
	ReadPara()
}

// SUMMARY-PARA
func SummaryPara() {
	line := "LABELS: " + formatPic9(WsCount, 3) + " A-TOTAL: " + formatPic9(WsTotalA, 3)
	fmt.Fprintln(os.Stdout, line)
}

// MAIN-PARA
func MainPara() {
	if err := openPartFile(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	closePartFile()
	SummaryPara()
}

func main() {
	MainPara()
}
